76	    // --- Verificar se já existe escrow postpago para este job (idempotência + proteção) ---
77	    // Busca SEM filtro de status: trata cada estado de forma explícita para não criar
78	    // holds adicionais no cartão da empresa sem novo consentimento.
79	    const { data: existingEscrow } = await supabaseAdmin
80	      .from('escrow_transactions')
81	      .select('id, asaas_payment_id, status')
82	      .eq('job_id', jobId)
83	      .eq('kind', 'postpaid')
84	      .maybeSingle();
85	
86	    if (existingEscrow) {
87	      if (existingEscrow.status === 'authorized') {
88	        // Já autorizado — idempotência: retorna o existente sem criar 2º hold
