92	            escrowId: existingEscrow.id,
93	            asaasPaymentId: existingEscrow.asaas_payment_id,
94	            status: 'authorized',
95	            idempotent: true,
96	          }),
97	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
