99	      }
100	
101	      // Estado terminal: refunded / captured / released.
102	      // Não recriar hold sem novo convite/consentimento da empresa. Rejeitar explicitamente.
103	      return new Response(
104	        JSON.stringify({
105	          error:
106	            `Não é possível criar novo hold: o escrow deste turno já está em estado '${existingEscrow.status}'. ` +
107	            'Para um novo comprometimento de pagamento, a empresa deve emitir um novo convite.',
108	        }),
109	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 409 }
110	      );
111	    }
112	
113	    // --- Modo: 'authorize' | 'charge_on_demand' ---
114	    const mode = Deno.env.get('ASAAS_POSTPAGO_MODE') ?? 'authorize';
115	
116	    if (mode === 'charge_on_demand') {
117	      // Pula a pré-auth; captura será feita na conclusão. Retorna success sem escrow.
118	      console.log(`[authorize-payment] charge_on_demand mode: skip hold for job=${jobId}`);
119	      return new Response(
120	        JSON.stringify({ success: true, status: 'charge_on_demand', mode }),
121	        { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
122	      );
123	    }
124	
125	    // --- Buscar dados do job (valor + company_id) ---
126	    const { data: job, error: jobErr } = await supabaseAdmin
127	      .from('jobs')
128	      .select('company_id, budget, title')
129	      .eq('id', jobId)
130	      .maybeSingle();
131	
132	    if (jobErr || !job) throw new Error('Vaga não encontrada.');
133	    const amount: number = job.budget;
134	    if (!amount || amount <= 0) throw new Error('Budget da vaga inválido para pré-autorização.');
135	
136	    const companyUserId: string = job.company_id;
137	
138	    // --- Buscar método de pagamento default da empresa ---
139	    const { data: pm, error: pmErr } = await supabaseAdmin
140	      .from('payment_methods')
141	      .select('asaas_credit_card_token, brand, last4')
142	      .eq('company_id', companyUserId)
143	      .eq('is_default', true)
144	      .maybeSingle();
145	
146	    if (pmErr || !pm) {
147	      throw new Error(
148	        'A empresa não possui método de pagamento cadastrado. ' +
149	        'Solicite ao operador que cadastre um cartão antes de aceitar convites.'
150	      );
151	    }
152	
153	    // --- Buscar asaas_customer_id da empresa ---
154	    const { data: companyWallet, error: cwErr } = await supabaseAdmin
155	      .from('wallets')
156	      .select('asaas_customer_id')
157	      .eq('user_id', companyUserId)
158	      .maybeSingle();
159	
160	    if (cwErr || !companyWallet?.asaas_customer_id) {
161	      throw new Error('Conta de pagamento da empresa não encontrada no Asaas.');
162	    }
163	
164	    // --- remoteIp (exigido pelo Asaas para cobrança com cartão) ---
165	    const remoteIp =
166	      req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
167	      req.headers.get('x-real-ip') ||
168	      '0.0.0.0';
169	
170	    // dueDate = hoje + 1 dia (mínimo exigido pelo Asaas)
171	    const dueDate = new Date();
172	    dueDate.setDate(dueDate.getDate() + 1);
173	    const dueDateStr = dueDate.toISOString().split('T')[0];
174	
175	    // --- POST /v3/payments com authorizeOnly:true ---
176	    const paymentRes = await fetch(`${ASAAS_API_URL}/payments`, {
177	      method: 'POST',
178	      headers: getAsaasHeaders(),
179	      body: JSON.stringify({
180	        customer: companyWallet.asaas_customer_id,
181	        billingType: 'CREDIT_CARD',
182	        value: amount,
183	        dueDate: dueDateStr,
184	        description: `Turno reservado: ${job.title}`,
185	        externalReference: jobId,
186	        authorizeOnly: true,
187	        creditCardToken: pm.asaas_credit_card_token,
188	        remoteIp,
189	      }),
190	    });
191	
192	    const paymentData = await paymentRes.json();
193	
194	    // --- Tratar falha: distinguir "pré-auth não habilitada" de recusa de cartão ---
195	    if (!paymentRes.ok) {
196	      const errCode: string = paymentData.errors?.[0]?.code ?? '';
197	      const errMsg: string = paymentData.errors?.[0]?.description || paymentData.error || '';
198	
199	      // Códigos específicos do Asaas que indicam que a funcionalidade de pré-autorização
200	      // não está habilitada na conta (configuração do merchant, não recusa de cartão).
201	      // Referência: documentação Asaas — "authorizeOnly not available for this account".
202	      const PRE_AUTH_UNAVAILABLE_CODES = new Set([
203	        'invalid_action',
204	        'INVALID_ACTION',
205	        'authorize_only_not_available',
206	        'AUTHORIZE_ONLY_NOT_AVAILABLE',
207	      ]);
208	
209	      const isPreAuthDisabled =
210	        PRE_AUTH_UNAVAILABLE_CODES.has(errCode) ||
211	        errMsg.toLowerCase().includes('authorize_only') ||
212	        errMsg.toLowerCase().includes('authorizeonly') ||
213	        errMsg.toLowerCase().includes('pre-authorization not available') ||
214	        errMsg.toLowerCase().includes('pré-autorização não disponível');
215	
216	      if (isPreAuthDisabled) {
217	        console.warn(
218	          `[authorize-payment] Pré-auth não disponível na conta (fallback charge_on_demand): ` +
219	          `code=${errCode} msg=${errMsg}`
220	        );
221	        return new Response(
222	          JSON.stringify({ success: true, status: 'charge_on_demand', fallback: true, reason: errMsg }),
223	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
224	        );
225	      }
226	
227	      // Qualquer outro erro (incluindo recusa de cartão) deve ser surfaced — não engolir.
228	      console.error(
229	        `[authorize-payment] Falha na pré-autorização: code=${errCode} status=${paymentRes.status} msg=${errMsg}`
230	      );
231	      throw new Error(errMsg || 'Erro ao criar pré-autorização no Asaas.');
232	    }
233	
234	    const asaasPaymentId: string = paymentData.id;
235	    if (!asaasPaymentId) throw new Error('Asaas não retornou o id da cobrança.');
236	
237	    // Status esperado: AUTHORIZED. Se não, logar mas prosseguir (Asaas pode retornar PENDING transitório)
238	    if (paymentData.status && paymentData.status !== 'AUTHORIZED') {
239	      console.warn(
240	        `[authorize-payment] Status Asaas inesperado: ${paymentData.status} para payment=${asaasPaymentId}`
241	      );
242	    }
243	
244	    // --- Gravar escrow 'authorized'/'postpaid' no DB (RPC atômica) ---
245	    const { data: escrowId, error: rpcErr } = await supabaseAdmin.rpc(
246	      'authorize_escrow_postpago',
247	      {
248	        p_job_id: jobId,
249	        p_application_id: applicationId,
250	        p_amount: amount,
251	        p_asaas_payment_id: asaasPaymentId,
252	        p_company_user_id: companyUserId,
253	      }
254	    );
255	
256	    if (rpcErr) {
257	      // 23505 = único violado (hold duplicado) — tratar como idempotente
258	      if (rpcErr.code === '23505') {
259	        console.warn(`[authorize-payment] Escrow duplicado (23505), tratando como idempotente.`);
260	        return new Response(
261	          JSON.stringify({ success: true, asaasPaymentId, status: 'authorized', idempotent: true }),
262	          { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
263	        );
264	      }
265	      // RPC falhou após criar o hold no Asaas — logar para reconciliação manual
266	      console.error(
267	        `[authorize-payment] RPC authorize_escrow_postpago falhou após hold criado. ` +
268	        `asaas_payment_id=${asaasPaymentId} job=${jobId}. Erro: ${rpcErr.message}`
269	      );
270	      throw new Error('Falha ao registrar escrow. O hold foi criado no Asaas — contacte o suporte.');
271	    }
272	
273	    return new Response(
274	      JSON.stringify({
275	        success: true,
276	        escrowId,
277	        asaasPaymentId,
278	        status: 'authorized',
279	      }),
280	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 200 }
281	    );
282	  } catch (error: unknown) {
283	    const msg = error instanceof Error ? error.message : 'Erro interno.';
284	    console.error('asaas-authorize-payment error:', msg);
285	    return new Response(
286	      JSON.stringify({ error: msg }),
287	      { headers: { ...corsHeaders, 'Content-Type': 'application/json' }, status: 400 }
288	    );
289	  }
290	});
