56	        const { data: newWallet, error } = await supabase
57	            .from('wallets')
58	            .insert({ user_id: userId, balance: 0.00, user_type: userType })
59	            .select()
60	            .single();
61	
62	        if (error) {
63	            logError('Error creating wallet', error);
64	            return null;
65	        }
66	
67	        return newWallet as Wallet;
68	    },
69	
70	    async withdrawFunds(amount: number, pixKey: string, pixKeyType: string = 'CPF'): Promise<{ success: boolean; error?: string }> {
71	        try {
72	            await invokeFunction('asaas-withdraw', { amount, pixKey, pixKeyType });
73	            return { success: true };
74	        } catch (error: unknown) {
75	            logError('Error withdrawing funds', error);
76	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao realizar saque' };
77	        }
78	    },
79	
80	    async getBalance(userId: string): Promise<number> {
81	        const { data } = await supabase
82	            .from('wallets')
83	            .select('balance')
84	            .eq('user_id', userId)
85	            .single();
