39	/**
40	 * Invoca asaas-authorize-payment após o aceite do convite.
41	 * Retorna um resultado estruturado:
42	 *  - 'ok'                    : hold criado com sucesso.
43	 *  - 'fallback_charge_on_demand': pré-auth não habilitada; cobrança será na conclusão.
44	 *  - 'card_declined'         : cartão recusado — empresa deve verificar o método de pagamento.
45	 *
46	 * Falha NÃO reverte o status 'hired' — o aceite já aconteceu no DB.
47	 * Em 'card_declined', uma notificação in-app é criada para a empresa.
48	 */
49	async function dispatchAuthorizePayment(
50	  jobId: string,
51	  applicationId: string,
52	  companyOwnerId: string,
53	): Promise<AuthorizePaymentOutcome> {
54	  try {
55	    // invokeFunction lança se HTTP status >= 400 (comportamento padrão de api.ts)
56	    const result = await invokeFunction('asaas-authorize-payment', { jobId, applicationId }) as {
57	      success?: boolean;
58	      status?: string;
59	      fallback?: boolean;
60	      reason?: string;
61	      asaasPaymentId?: string;
62	    };
63	
64	    if (result?.status === 'charge_on_demand') {
65	      return { kind: 'fallback_charge_on_demand', reason: result.reason ?? '' };
66	    }
67	
68	    return { kind: 'ok', asaasPaymentId: result?.asaasPaymentId ?? '' };
69	  } catch (authErr) {
70	    const errMsg = authErr instanceof Error ? authErr.message : 'Erro desconhecido na autorização.';
71	
72	    // Detectar estado terminal (HTTP 409): o escrow deste turno já passou por captura/liberação.
73	    // A mensagem vinda da edge function contém "estado terminal" ou "já está em estado" (409).
74	    // Neste caso o turno já foi pago — NÃO é recusa de cartão; não notificar a empresa.
75	    const isTerminalState =
76	      errMsg.includes('estado terminal') ||
77	      errMsg.includes('já está em estado') ||
78	      errMsg.includes('Não é possível criar novo hold');
79	
80	    if (isTerminalState) {
81	      // Logar para rastreabilidade, mas sem notificação de "cartão recusado"
82	      logError('shiftInvite.authorizePayment (terminal state — turno já pago)', authErr);
83	      return { kind: 'fallback_charge_on_demand', reason: errMsg };
84	    }
85	
86	    // Detectar recusa de cartão: a Edge Function agora lança erros específicos (não engole mais
87	    // recusas). Qualquer erro que não seja "pré-auth não disponível" nem "estado terminal" é
88	    // tratado como card_declined para fins de notificação.
89	    logError('shiftInvite.authorizePayment (best-effort)', authErr);
90	
91	    // Notificar empresa sobre falha no cartão (best-effort — não bloqueia o aceite)
92	    if (companyOwnerId) {
93	      try {
94	        await supabase.from('notifications').insert({
95	          user_id: companyOwnerId,
96	          type: 'payment',
97	          title: 'Falha na autorização do cartão',
98	          message:
99	            `A autorização do pagamento para o turno falhou: ${errMsg}. ` +
100	            'Verifique o método de pagamento cadastrado para garantir que o freela receba.',
101	          link: '/company/wallet',
102	        });
103	      } catch (notifErr) {
104	        logError('shiftInvite.authorizePayment.notif', notifErr);
105	      }
106	    }
107	
108	    return { kind: 'card_declined', errorMsg: errMsg };
109	  }
110	}
